def transform(grid):
    h, w = len(grid), len(grid[0])

    # The full line of 2s is the surface toward which the objects move.
    if all(x == 2 for x in grid[0]):
        direction = -1
        barrier = {(0, c) for c in range(w)}
    elif all(x == 2 for x in grid[-1]):
        direction = 1
        barrier = {(h - 1, c) for c in range(w)}
    elif all(grid[r][0] == 2 for r in range(h)):
        direction = 0
        barrier = {(r, 0) for r in range(h)}
    elif all(grid[r][-1] == 2 for r in range(h)):
        direction = 2
        barrier = {(r, w - 1) for r in range(h)}
    else:
        return [row[:] for row in grid]

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            cells = {(r, c)}
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        cells.add((ny, nx))
                        stack.append((ny, nx))
            objects.append([color, cells])

    occupied = set(barrier)
    # Move the objects nearest the surface first.
    if direction == -1:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
        dr, dc = -1, 0
    elif direction == 1:
        objects.sort(key=lambda obj: -max(r for r, c in obj[1]))
        dr, dc = 1, 0
    elif direction == 0:
        objects.sort(key=lambda obj: min(c for r, c in obj[1]))
        dr, dc = 0, -1
    else:
        objects.sort(key=lambda obj: -max(c for r, c in obj[1]))
        dr, dc = 0, 1

    settled = []
    for color, cells in objects:
        while True:
            moved = {(r + dr, c + dc) for r, c in cells}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in moved):
                break
            if moved & occupied:
                break
            cells = moved
        occupied.update(cells)
        settled.append((color, cells))

    out = [[0] * w for _ in range(h)]
    for r, c in barrier:
        out[r][c] = 2
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
